"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[14077],{88095:e=>{e.exports=JSON.parse('{"functions":[{"name":"ComputeHoldDuration","desc":"Linearly interpolates the required hold duration based on how many junk\\nitems the player is shredding.\\n\\nThe duration scales from `config.MIN_HOLD_DURATION` (when `junkCount = 1`)\\nto `config.MAX_HOLD_DURATION` (when `junkCount >= config.MAX_JUNK_COUNT`).\\n`junkCount` is clamped to `[1, MAX_JUNK_COUNT]` before interpolation.\\n\\nWhen `MAX_JUNK_COUNT` is 1, `MAX_HOLD_DURATION` is returned immediately.","params":[{"name":"junkCount","desc":"Number of junk items being shredded (\u2265 1).","lua_type":"number"},{"name":"config","desc":"Duration and count thresholds (from `Configs/ShredderConfig`).","lua_type":"HoldDurationConfig"}],"returns":[{"desc":"Required hold duration in seconds.","lua_type":"number"}],"function_type":"static","source":{"line":36,"path":"src/ReplicatedStorage/SharedModules/ShredderMath.luau"}}],"properties":[],"types":[],"name":"ShredderMath","desc":"Pure math helpers for the shredder system, shared by `ShredderServer` and\\nany client code that needs to display hold-duration feedback.\\n\\nAll functions are stateless; no Roblox services are referenced.","source":{"line":19,"path":"src/ReplicatedStorage/SharedModules/ShredderMath.luau"}}')}}]);